// Combine SerpAPI trend results with the list of existing slugs.
// Output a single object with `trends` (string) and `existingSlugs` (string[]).

const trendsItem = $('SerpAPI: Google Trends').first().json || {};
const rising = (trendsItem.related_queries && trendsItem.related_queries.rising) || [];
const top    = (trendsItem.related_queries && trendsItem.related_queries.top)    || [];

// Multi-query responses come as arrays keyed by query — flatten if needed.
let flatRising = rising;
let flatTop    = top;
if (Array.isArray(trendsItem.related_queries_list)) {
  flatRising = trendsItem.related_queries_list.flatMap(x => (x.rising || []));
  flatTop    = trendsItem.related_queries_list.flatMap(x => (x.top    || []));
}

const rows = $('Supabase: Get Existing Slugs').first().json || [];
const existingSlugs  = Array.isArray(rows) ? rows.map(r => r.slug).filter(Boolean) : [];
const existingTitles = Array.isArray(rows) ? rows.map(r => r.title).filter(Boolean) : [];

const trendsText = [
  '## Rising (last month)',
  ...flatRising.slice(0, 25).map(x => `- ${x.query} (${x.value || ''})`),
  '',
  '## Top',
  ...flatTop.slice(0, 25).map(x => `- ${x.query} (${x.value || ''})`),
].join('\n');

return [{
  json: {
    trends: trendsText || 'No trends data, fall back to general Pakistan travel inspiration.',
    existingSlugs,
    existingTitles,
    runId: `n8n_${$execution.id}`,
    today: new Date().toISOString().slice(0, 10),
  }
}];

// Parse the OpenAI response into a clean post object.
const raw = $input.first().json;
const content = raw?.choices?.[0]?.message?.content || '';

let post;
try {
  // Strip any accidental code fences just in case.
  const cleaned = content.replace(/^```(json)?/i, '').replace(/```$/, '').trim();
  post = JSON.parse(cleaned);
} catch (err) {
  throw new Error('OpenAI did not return valid JSON. Raw content: ' + content.slice(0, 500));
}

const required = ['slug','title','excerpt','content','category','image_prompt'];
for (const k of required) {
  if (!post[k] || typeof post[k] !== 'string' || !post[k].trim()) {
    throw new Error(`Missing required field: ${k}`);
  }
}

// Belt-and-suspenders: strip any em dashes the model snuck in.
for (const k of ['title','excerpt','content','seo_title','seo_desc','image_alt']) {
  if (typeof post[k] === 'string') post[k] = post[k].replace(/—/g, ' - ');
}

// Normalise slug.
post.slug = post.slug.toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

// Clamp category to allowed enum.
const allowed = ['Adventure','Culture','Food','Nature','Other'];
if (!allowed.includes(post.category)) post.category = 'Other';

// Defaults.
post.tags = Array.isArray(post.tags) ? post.tags.slice(0, 8) : [];
post.read_time = Number.isFinite(+post.read_time) ? Math.max(3, Math.min(20, +post.read_time)) : 6;
post.seo_title = post.seo_title || post.title;
post.seo_desc  = post.seo_desc  || post.excerpt;
post.image_alt = post.image_alt || post.title;

post.runId = $('Build Context for OpenAI').first().json.runId;

return [{ json: post }];

