// Pull base64 image data out of the Gemini response and attach as binary.
const gem = $input.first().json;
const parts = gem?.candidates?.[0]?.content?.parts || [];
const inline = parts.find(p => p.inlineData)?.inlineData;

if (!inline?.data) {
  throw new Error('Gemini did not return an image. Response: ' + JSON.stringify(gem).slice(0, 500));
}

const post = $('Parse Post JSON').first().json;
const mimeType = inline.mimeType || 'image/png';
const ext = mimeType.includes('jpeg') ? 'jpg' : 'png';

return [{
  json: { ...post, imageMimeType: mimeType, imageExt: ext },
  binary: {
    image: {
      data: inline.data,
      mimeType,
      fileName: `${post.slug}.${ext}`,
      fileExtension: ext,
    }
  }
}];

// Build the public image URL and final post payload for insert.
const post = $('Extract Image to Binary').first().json;
const supabaseUrl = $env.SUPABASE_URL;
const publicImageUrl = `${supabaseUrl}/storage/v1/object/public/blog-images/${post.slug}.${post.imageExt}`;

return [{
  json: {
    slug: post.slug,
    title: post.title,
    excerpt: post.excerpt,
    content: post.content,
    image_url: publicImageUrl,
    image_alt: post.image_alt,
    category: post.category,
    tags: post.tags,
    author: 'Ahmad Fraz',
    status: 'draft',
    read_time: post.read_time,
    seo_title: post.seo_title,
    seo_desc: post.seo_desc,
    seo_image: publicImageUrl,
    n8n_run_id: post.runId,
    ai_generated: true,
  }
}];
